יג. יֵשׁ מְקוֹמוֹת הָרְחוֹקִים מְאֹד מִכְּבוֹדוֹ יִתְבָּרַךְ, וַעֲלֵיהֶם נֶאֱמַר: "וּכְבוֹדֵי לְאַחֵר לֹא אֶתֵּן", וּכְשֶׁנּוֹפֵל הָאָדָם לְשָׁם, חַס וְשָׁלוֹם, וְרוֹאֶה שֶׁהוּא רָחוֹק מְאֹד מִכְּבוֹדוֹ יִתְבָּרַךְ, וְשׁוֹאֵל וּמְחַפֵּשׂ וּמְבַקֵּשׁ גַּם מִשָּׁם אַחַר כְּבוֹדוֹ יִתְבָּרַךְ בִּבְחִינַת "אַיֵּה מְקוֹם כְּבוֹדוֹ", אֲזַי זֶה עִקַּר תְּשׁוּבָתוֹ וְיָכוֹל לַעֲלוֹת עַל־יְדֵי־זֶה בְּתַכְלִית הָעֲלִיָּה, כִּי בְּחִינַת "אַיֵּה" הַנַּ"ל הוא בְּחִינַת הַמַּאֲמָר סָתוּם, שֶׁמִּמֶּנּוּ יוֹנְקִים כָּל הָעֲשָׂרָה מַאֲמָרוֹת, שֶׁהָיָה בִּשְׁבִיל הִתְגַּלּוּת כְּבוֹדוֹ יִתְבָּרַךְ, כַּמְבֹאָר כָּל עִנְיָן זֶה בִּדְבָרֵינוּ כַּמָּה פְּעָמִים. אַךְ אִי אֶפְשָׁר לִזְכּוֹת בִּשְׁלֵמוּת לִבְחִינַת הַבַּקָּשָׁה וְהַחִפּוּשׂ הַנַּ"ל עַד שֶׁיַּעֲלֶה עַל־יְדֵי־זֶה בְּתַכְלִית הָעֲלִיָּה כַּנַּ"ל, כִּי אִם כְּשֶׁהוּא עָנָו וְשָׁפָל וּמְבַטֵּל לְעֵת־עַתָּה עַל־כָּל־פָּנִים כְּבוֹד עַצְמוֹ, וְאֵינוֹ חוֹשֵׁשׁ לִכְבוֹד עַצְמוֹ כְּלָל רַק לִכְבוֹד הַשֵּׁם יִתְבָּרַךְ, אֲזַי הוּא יָכוֹל לְבַקֵּשׁ אֶת ה' בִּבְחִינַת "בַּקְּשׁוּ אֶת ה' כָּל עַנְוֵי הָאָרֶץ" - עַנְוֵי אֶרֶץ דַּיְקָא, כִּי כָל זְמַן שֶׁהָאָדָם רוֹדֵף אַחַר כְּבוֹד עַצְמוֹ, נִמְצָא שֶׁיֵּשׁ כָּבוֹד אַחֵר חוּץ מִכְּבוֹדוֹ יִתְבָּרַךְ. וְעַל־כֵּן אָמְרוּ רַבּוֹתֵינוּ זַ"ל בֶּאֱמֶת עַל הַמִּתְגָּאֶה, שֶׁהוּא כְּאִלּוּ עוֹבֵד עֲבוֹדָה זָרָה, וַאֲזַי הוּא רָחוֹק עַל־יְדֵי־זֶה בְּעַצְמוֹ מִכְּבוֹדוֹ יִתְבָּרַךְ בְּיוֹתֵר בְּתַכְלִית הָרִחוּק, כִּי כָּל הָרוֹדֵף אַחַר הַכָּבוֹד - הַכָּבוֹד דִּקְדֻשָּׁה בּוֹרֵחַ מִמֶּנּוּ, כִּי עַל אֵלּוּ הַמְּקוֹמוֹת שֶׁהֵם בְּחִינַת עֲבוֹדָה זָרָה נֶאֱמַר: "וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן", וַאֲזַי נִסְתָּר וְנֶעְלָם מִמֶּנּוּ כְּבוֹדוֹ יִתְבָּרַךְ בְּתַכְלִית הַהַסְתָּרָה, עַד שֶׁאֵין יְכוֹלִין אֲפִלּוּ לְבַקֵּשׁ וּלְחַפֵּשׂ אַיֵּה מְקוֹם כְּבוֹדוֹ, כִּי אֵין יוֹדְעִין כְּלָל מִכְּבוֹדוֹ יִתְבָּרַךְ, כִּי הוּא נִסְתָּר וְנֶעְלָם בְּתַכְלִית הַהַסְתָּרָה עַל־יְדֵי הִתְגַּבְּרוּת כָּבוֹד אַחֵר, חַס וְשָׁלוֹם, כַּנַּ"ל. אֲבָל כְּשֶׁמְּבַטְּלִין כָּל מִינֵי כָּבוֹד אַחֵר וְאֵין מַשְׁגִּיחִין עַל כְּבוֹד עַצְמוֹ כְּלָל, רַק רוֹצִין בִּכְבוֹד הַשֵּׁם יִתְבָּרַךְ, אֲזַי אַף־עַל־פִּי שֶׁעֲדַיִן הוּא רָחוֹק מְאֹד מִכְּבוֹדוֹ יִתְבָּרַךְ מֵחֲמַת שֶׁנָּפַל לְמָקוֹם שֶׁנָּפַל, אַף־עַל־פִּי־כֵן עַל־יְדֵי שֶׁהוּא מְבַקֵּשׁ וּמְחַפֵּשׂ אַיֵּה מְקוֹם כְּבוֹדוֹ, כִּי מֵאַחַר שֶׁאֵינוֹ רוֹצֶה בִּכְבוֹד אַחֵר רַק בִּכְבוֹדוֹ יִתְבָּרַךְ, עַל־כֵּן אַף־עַל־פִּי שֶׁהוּא בְּמַדְרֵגָה הַתַּחְתּוֹנָה מְאֹד, אַף־עַל־פִּי־כֵן הוּא מְחַפֵּשׂ אַיֵּה מְקוֹם כְּבוֹדוֹ, וְעַל־יְדֵי־זֶה עֲלִיָּתוֹ וְתִקּוּנוֹ כַּנַּ"ל. וְזֶה מְרֻמָּז בְּדִבְרֵי רַבּוֹתֵינוּ זַ"ל, שֶׁאָמְרוּ, שֶׁכָּל הָאִסּוּרִין בְּטֵלִין בְּשִׁשִּׁים חוּץ מֵחֲתִיכָה הָרְאוּיָה לְהִתְכַּבֵּד וּשְׁאָר דְּבָרִים חֲשׁוּבִים. כִּי שֹׁרֶשׁ הָעִנְיָן מַה שֶּׁיָּכוֹל הָאִסּוּר לְהִתְבַּטֵּל וּלְהִתְהַפֵּךְ לְהֶתֵּר, זֶה נִמְשָׁךְ מִבְּחִינַת מַאֲמָר סָתוּם הַנַּ"ל, שֶׁעַל־יְדֵי הַבַּקָּשָׁה וְהַחִפּוּשׂ אַיֵּה מְקוֹם כְּבוֹדוֹ הַנַּ"ל זוֹכִין לַעֲלוֹת לִבְחִינַת "אַיֵּה" בְּשָׁרְשׁוֹ הָעֶלְיוֹן דִּקְדֻשָּׁה, שֶׁהוּא בְּחִינַת הַמַּאֲמָר סָתוּם, וְשָׁם יְכוֹלִין כָּל הַיְרִידוֹת לְהִתְהַפֵּךְ לַעֲלִיּוֹת גְּדוֹלוֹת, אֲבָל צְרִיכִין עַל־ כָּל־פָּנִים לְעֵת־עַתָּה לְבַטֵּל כְּבוֹד עַצְמוֹ, שֶׁלֹּא יִהְיֶה בְּעֵינָיו בִּבְחִינַת חֲתִיכָה הָרְאוּיָה לְהִתְכַּבֵּד וְדָבָר חָשׁוּב, כִּי אָז בְּחִינַת הָאִסּוּר שֶׁלּוֹ אֵינוֹ יָכוֹל לְהִתְבַּטֵּל, כִּי אָז אִי אֶפְשָׁר לוֹ לִזְכּוֹת בִּשְׁלֵמוּת לְהַבַּקָּשָׁה וְחִפּוּשׂ הַנַּ"ל. וְעַל־כֵּן בֶּאֱמֶת, זֹאת הַבְּחִינָה, שֶׁהַיְרִידָה תִּתְהַפֵּךְ לַעֲלִיָּה גְדוֹלָה עַל־יְדֵי הַבַּקָּשָׁה וְחִפּוּשׂ "אַיֵּה" הַנַּ"ל, אִי אֶפְשָׁר לִזְכּוֹת לָזֶה בִּשְׁלֵמוּת כִּי אִם בְּכֹחַ הַהִתְקָרְבוּת לְהַצַּדִּיקִים וּכְשֵׁרִים אֲמִתִּיִּים, הַמְבַטְּלִים כְּבוֹד עַצְמָם לְגַמְרֵי וְעוֹסְקִים כָּל יְמֵיהֶם בְּתוֹרָה וַעֲבוֹדַת־הַשֵּׁם, לְגַדֵּל וּלְרוֹמֵם כְּבוֹד ה' עַל־יְדֵי כְּלַל הַבְּרִיאָה שֶׁנִּבְרָא בַּעֲשָׂרָה מַאֲמָרוֹת שֶׁיּוֹנְקִים מֵהַמַּאֲמָר סָתוּם, שֶׁמֵּחֲמַת גֹּדֶל הַהַעְלָמָה וְהַהַסְתָּרָה שֶׁיֶּשׁ שָׁם, עַל־יְדֵי־ זֶה מִשְׁתַּלְשֵׁל מִשָּׁם יְנִיקַת הַסִּטְרָא־אָחֳרָא וְהַכְּפִירוֹת, רַחֲמָנָא לִצְּלַן, שֶׁרוֹצִים לְהַעְלִים וּלְהַסְתִּיר לְגַמְרֵי כְּבוֹד אֱלָקוּתוֹ יִתְבָּרַךְ. וְהַצַּדִּיקִים וְהַכְּשֵׁרִים הַנַּ"ל, בְּגֹדֶל מַעֲלַת קְדֻשַּׁת עֲבוֹדָתָם זוֹכִין לְהַמְשִׁיךְ מִשָּׁם דַּיְקָא כָּל הַקְּדֻשּׁוֹת וְכָל הַיְדִיעוֹת מֵהַשֵּׁם יִתְבָּרַךְ, שֶׁזֶּה בְּחִינַת הִתְגַּלּוּת כְּבוֹדוֹ שֶׁעַל־יְדֵי כָּל הַמַּאֲמָרוֹת, שֶׁבֶּאֱמֶת נִמְשָׁכִין כֻּלָּם בְּשָׁרְשָׁן מֵהַמַּאֲמָר סָתוּם הַנַּ"ל, עַל־כֵּן הֵם יְכוֹלִין לְהַמְשִׁיךְ הֶאָרָה מֵהַמַּאֲמָר סָתוּם הַנַּ"ל אֲפִלּוּ עַל כָּל הָרְחוֹקִים וְהַנּוֹפְלִים, שֶׁיִּתְעוֹרְרוּ גַּם הֵם לְחַפֵּשׂ וּלְבַקֵּשׁ אַחַר כְּבוֹדוֹ יִתְבָּרַךְ גַּם מִמְּקוֹמָם הַשָּׁפָל וְהַנָּמוּךְ, עַד שֶׁעַל יְדֵי זֶה עוֹלִין אַחַר כָּךְ עַל יְדֵי זֶה דַּיְקָא בְּתַכְלִית הָעֲלִיָּה כַּנַּ"ל. עַיֵּן עוֹד פְּנִים, שָׁם מְבֹאָר עוֹד יוֹתֵר עִנְיָן זֶה וְעִנְיַן בִּטּוּל הָאִסּוּר בְּשִׁשִּׁים דַּיְקָא (הלכות תערובות, הלכה ב). 
יד. עַל־יְדֵי שֶׁיּוֹדֵעַ שִׁפְלוּתוֹ בֶּאֱמֶת וּמֵשִׂים עַצְמוֹ כֶּעָפָר מַמָּשׁ, עַל־יְדֵי־זֶה זוֹכֶה לְהִסְתַּכֵּל עַל הָאֱמֶת לַאֲמִתּוֹ וְשֶׁיִּתְגַּלֶּה לוֹ אוֹר הָאֱמֶת, עַד שֶׁזּוֹכֶה עַל־יְדֵי־זֶה לְהִתְגַּבֵּר בְּחֵשֶׁק וְרָצוֹן דִּקְדֻשָּׁה, עַד שֶׁנִּשְׁבָּר עַל־יְדֵי־ זֶה כָּל הַמְּנִיעוֹת וְיִזְכֶּה לְהִתְקָרֵב אֶל הַקְּדֻשָּׁה וּלְהוֹצִיא כָּל הַדְּבָרִים שֶׁבִּקְדֻשָּׁה מִן הַכֹּחַ אֶל הַפֹּעַל בִּשְׁלֵמוּת (הל' הכשר כלים, הל' ד,

). 
יט. יָדוּעַ שֶׁיֵּשׁ שָׁלשׁ קְלִפּוֹת טְמֵאוֹת לְגַמְרֵי, וּקְלִפָּה רְבִיעִית הִיא נֹגַהּ, שֶׁהוּא מְעֹרָב טוֹב וָרָע. וְאֵלּוּ הָאַרְבַּע קְלִפּוֹת צָרִיךְ כָּל אָדָם לְשַׁבְּרָם וּלְבַטְּלָם, כִּי זֶה עִקַּר הַנִּסָּיוֹן וְהַבְּחִירָה שֶׁל הָאָדָם, לַעֲמֹד כְּנֶגֶד כָּל הַמִּדּוֹת רָעוֹת הַנִּמְשָׁכִין מֵאֵלּוּ הָאַרְבַּע קְלִפּוֹת הַקּוֹדְמִין לַפְּרִי, וְעַל־יְדֵי־זֶה יִזְכֶּה לַפֶּרִי. וּכְלַל כָּל הַמִּדּוֹת רָעוֹת כְּלוּלִים בְּגֵאוּת, שֶׁהוּא עֲבוֹדָה זָרָה, וְהוּא הַהֵפֶךְ מִכָּל הַתּוֹרָה שֶׁעִקָּרָהּ עֲנָוָה בְּחִינַת אַיִן. כִּי כְּלַל כָּל הַתּוֹרָה הוּא לְבַטֵּל עַצְמוֹ בְּתַכְלִית הַבִּטּוּל, עַד שֶׁיִּהְיֶה נִכְלָל בְּאֵין־סוֹף, וְגֵאוּת הוּא הַהֵפֶךְ מַמָּשׁ מִזֶּה, כִּי גֵּאוּת כָּלוּל מִכָּל הָאַרְבַּע קְלִפּוֹת הַנַּ"ל שֶׁצְּרִיכִין לְשַׁבְּרָם עַל־ יְדֵי אַרְבַּע בְּחִינוֹת שִׁפְלוּת, הַיְנוּ, שֶׁיִּהְיֶה שָׁפָל נֶגֶד גְּדוֹלִים, וּבֵינוֹנִים, וּקְטַנִּים, וְעוֹד צָרִיךְ לְהַקְטִין וּלְבַטֵּל אֶת עַצְמוֹ, עַד שֶׁיִּהְיֶה שָׁפָל בְּעֵינָיו לְמַטָּה מִמַּדְרֵגַת עַצְמוֹ וְיַחֲזִיק אֶת עַצְמוֹ לְמַטָּה מִמַּדְרֵגָתוֹ, בִּבְחִינַת "שְׁבוּ אִישׁ תַּחְתָּיו", וְעַל־יְדֵי־זֶה זוֹכֶה לְשַׁבֵּר כָּל הָאַרְבַּע קְלִפּוֹת הַנַּ"ל, כַּמְבֹאָר בִּפְנִים. וְזֶהוּ בְּחִינַת תִּקּוּן עֵץ־הַדַּעַת, שֶׁהָיָה רַק עַל־יְדֵי גֵּאוּת שֶׁהִכְנִיס בָּהֶם הַנָּחָשׁ, שֶׁאָמַר לָהֶם: "וִהְיִיתֶם כֵּאלֹקִים וְכוּ'", וְאָז זוֹכֶה לְבָרֵר הָאַרְבָּעָה יְסוֹדוֹת שֶׁלּוֹ עַד שֶׁיִּהְיוּ נִכְלָלִין בְּאַרְבַּע אוֹתִיּוֹת הַשֵּׁם, עַד שֶׁזּוֹכֶה לִהְיוֹת נִכְלָל בִּבְחִינַת קוֹצוֹ שֶׁל יוֹד שֶׁהוּא לְמַעְלָה מִן הַכֹּל כַּיָּדוּעַ, שֶׁשָּׁם אֵין שׁוּם אֲחִיזַת הָרַע כְּלָל. וְאָז כְּשֶׁזּוֹכִין לְבַטֵּל הַגֵּאוּת לְגַמְרֵי וְלָבוֹא לְתַכְלִית הָעֲנָוָה, שֶׁזֶּה עִקַּר הַקְּדֻשָּׁה, כִּי עִקַּר הַקְּדֻשָּׁה הוּא עֲנָוָה וְשִׁפְלוּת, אָז נִמְשָׁךְ עָלָיו בְּרָכָה וְשֶׁפַע רַב וְרַב־טוּב, בִּבְחִינַת 'מָאן דְּהוּא זְעֵיר הוּא רָב' (שם הלכה ה, אותיות ב ג ד). 
כ. כָּל־אֶחָד כְּפִי מַה שֶּׁמְּבַטֵּל אֶת עַצְמוֹ וּמַרְגִּישׁ שִׁפְלוּתוֹ בֶּאֱמֶת, כְּמוֹ־כֵן הוּא זוֹכֶה לְהִתְקָרֵב לְהַצַּדִּיק הָאֲמִתִּי, שֶׁכְּבָר זָכָה לְתַכְלִית הָעֲנָוָה בְּכָל הַבְּחִינוֹת עַד שֶׁהוּא בִּבְחִינַת מָה לְגַמְרֵי, שֶׁזֶּה עִקַּר מַעֲלַת וּגְדֻלַּת הַצַּדִּיק הָאֲמִתִּי, כִּי עֲנָוָה גְּדוֹלָה מִכֻּלָּם, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל. וְכֵן כָּל־מַה שֶׁמִּתְקָרֵב יוֹתֵר לְהַצַּדִּיק וְנִכְלָל בּוֹ, כְּמוֹ־כֵן הוּא זוֹכֶה לִבְחִינַת עֲנָוָה בֶּאֱמֶת, שֶׁזֶּה כָּל תִּקּוּנוֹ. כִּי עִקַּר הִתְרַחֲקוּת כָּל אָדָם מֵהַשֵּׁם יִתְבָּרַךְ וּמִצַּדִּיקֵי־אֱמֶת וּמֵהַתּוֹרָה הַקְּדוֹשָׁה, שֶׁהֵם כָּל חַיּוּתֵנוּ, הָעִקָּר הוּא מֵחֲמַת גֵּאוּת וְכָבוֹד, וְצָרִיךְ הָאָדָם לְהִשְׁתַּדֵּל לְבַטֵּל מִמֶּנּוּ כָּל הַבְּחִינוֹת גֵּאוּת בְּתַכְלִית הַבִּטּוּל, וְאָז יִזְכֶּה לְכָל־טוּב בֶּאֱמֶת (שם
